                    ("h2", "برای نگهداری هم جا در نظر بگیرید"),
                    ("p", "یک جای جداگانه برای هر قطعه، پیدا کردن زیورآلات و مرتب نگه داشتن آن‌ها را آسان‌تر می‌کند. درباره شیوه نگهداری و تمیز کردن همان مدل، به‌خصوص اگر نگین یا جزئیات ویژه دارد، راهنمای اختصاصی فروشگاه را دریافت کنید.")) },
            new { Slug="choosing-wedding-rings", Title="انتخاب حلقه ازدواج؛ زیبایی که با زندگی همراه می‌شود", Summary="حلقه‌ای که هر روز می‌پوشید باید هم دلخواهتان باشد و هم راحت. نگاهی به فرم، پهنا، اندازه و هماهنگی دو حلقه پیش از انتخاب.",
                Image="groom-demonstrates-two-wedding-rings-without-face_8353-11020-1.jpg", Body=BlogContent.FromParagraphs(
                    ("p", "حلقه ازدواج از آن انتخاب‌هایی است که قرار است مدت زیادی با شما همراه بماند. در کنار احساسی که به یک طرح دارید، به تجربه پوشیدن آن در روزهای معمولی هم فکر کنید؛ هنگام کار، نوشتن یا انجام کارهای روزمره."),
                    ("h2", "سادگی یا جزئیات؟"),
                    ("p", "حلقه ساده، بافت‌دار، نگین‌دار یا ترکیبی؛ انتخاب از سلیقه شما شروع می‌شود. چند طرح متفاوت را امتحان کنید و فقط به ظاهر آن در ویترین تکیه نکنید. فرم یک حلقه روی دست می‌تواند با تصوری که از عکسش دارید متفاوت باشد."),
                    ("h2", "پهنا و فرم داخلی را امتحان کنید"),
                    ("p", "دو حلقه با اندازه اسمی یکسان ممکن است حس متفاوتی روی انگشت داشته باشند. پهنا، ضخامت و فرم داخل حلقه در این تجربه مؤثرند. دست را باز و بسته کنید و مطمئن شوید لبه‌ها یا برجستگی‌ها برایتان آزاردهنده نیستند."),
                    ("h2", "اندازه را با راهنمای فروشگاه بررسی کنید"),
                    ("p", "برای تعیین اندازه از روش مورد تأیید فروشگاه استفاده کنید و اگر بین دو اندازه تردید دارید، کمک بگیرید. امکان تغییر اندازه برای همه طرح‌ها یکسان نیست؛ پیش از سفارش، به‌ویژه درباره حلقه‌های نگین‌دار یا حکاکی‌شده، این موضوع را بپرسید."),
                    ("h2", "هماهنگ بودن، الزاماً شبیه بودن نیست"),
                    ("p", "لازم نیست هر دو نفر دقیقاً یک طرح انتخاب کنند. می‌توانید رنگ، نوع پرداخت یا یک جزئیات کوچک را مشترک نگه دارید و پهنا یا فرم را مطابق سلیقه هر نفر انتخاب کنید. مهم این است که هر دو از پوشیدن حلقه خود احساس خوبی داشته باشید."),
                    ("h2", "به تصمیم زمان بدهید"),
                    ("p", "پس از انتخاب چند مدل، مشخصات و تصاویرشان را کنار هم مرور کنید. درباره زمان آماده شدن، حکاکی و خدمات پس از خرید پرس‌وجو کنید. انتخابی که با آرامش و شناخت انجام شود، بیشتر به سلیقه و زندگی شما نزدیک خواهد بود.")) }
        };
        var added = 0;
        foreach (var seed in seeds)
        {
            if (await db.Set<BlogPost>().AnyAsync(x => x.Slug == seed.Slug)) continue;
            var path = Path.Combine(environment.WebRootPath, "assets", "storefront", "images", seed.Image);
            db.Add(new BlogPost { Title=seed.Title, Slug=seed.Slug, Summary=seed.Summary, BodyJson=seed.Body,
                ImageData=await File.ReadAllBytesAsync(path), ImageContentType="image/jpeg", IsPublished=true,
                PublishedAtUtc=DateTime.UtcNow, UpdatedAtUtc=DateTime.UtcNow });
            added++;
        }
        await db.SaveChangesAsync();
        return added;
    }
}
